#include <bits/stdc++.h>
using namespace std;
const int MAXNODES = 10000010, INF_VAL = 0x3f3f3f3f;
int total_nodes, total_edges, c_param, d_param, k_param, total_flow_cost = 0;
int source = 0, sink, edge_idx = 1, head[MAXNODES], to[MAXNODES], next_edge[MAXNODES], capacity[MAXNODES], weight[MAXNODES];
int dist[MAXNODES], flow_limit[MAXNODES], parent_edge[MAXNODES]; bool in_queue[MAXNODES];

void add_edge(int u, int v, int cap, int w) {
	to[++edge_idx] = v; next_edge[edge_idx] = head[u]; head[u] = edge_idx; capacity[edge_idx] = cap; weight[edge_idx] = w;
	to[++edge_idx] = u; next_edge[edge_idx] = head[v]; head[v] = edge_idx; capacity[edge_idx] = 0; weight[edge_idx] = -w;
}
bool spfa() {
	memset(flow_limit, 0, sizeof(flow_limit));
	memset(dist, INF_VAL, sizeof(dist));
	memset(in_queue, 0, sizeof(in_queue));
	queue<int> q;
	q.push(source);
	flow_limit[source] = INF_VAL;
	in_queue[source] = true;
	dist[source] = 0;
	while (!q.empty()) {
		int u = q.front(); q.pop(); in_queue[u] = false;
		for (int i = head[u]; i; i = next_edge[i]) {
			if (!capacity[i] || dist[to[i]] <= dist[u] + weight[i]) continue;
			dist[to[i]] = dist[u] + weight[i];
			flow_limit[to[i]] = min(flow_limit[u], capacity[i]);
			parent_edge[to[i]] = i;
			if (!in_queue[to[i]]) {
				in_queue[to[i]] = true;
				q.push(to[i]);
			}
		}
	}
	return dist[sink] != INF_VAL;
}
void augment_flow() {
	int node = sink;
	while (node != source) {
		int i = parent_edge[node];
		capacity[i] -= flow_limit[sink];
		capacity[i ^ 1] += flow_limit[sink];
		node = to[i ^ 1];
	}
	total_flow_cost += flow_limit[sink] * dist[sink];
}
int main() {
	scanf("%d%d%d%d%d", &total_nodes, &total_edges, &k_param, &c_param, &d_param);
	sink = (total_nodes + k_param - 1) * total_nodes + 1;
	for (int i = 1, x; i <= k_param; i++) {
		scanf("%d", &x);
		add_edge(source, x, 1, 0);
	}
	for (int i = 1, x, y; i <= total_edges; i++) {
		scanf("%d%d", &x, &y);
		for (int j = 1; j <= total_nodes + k_param; j++)
			for (int h = 1; h <= k_param; h++) {
				add_edge(x + (j - 1) * total_nodes, y + j * total_nodes, 1, d_param * h * 2 - d_param + c_param);
				add_edge(y + (j - 1) * total_nodes, x + j * total_nodes, 1, d_param * h * 2 - d_param + c_param);
			}
	}
	for (int i = 1; i < total_nodes + k_param; i++) {
		for (int j = 2; j <= total_nodes; j++)
			add_edge(j + (i - 1) * total_nodes, j + i * total_nodes, INF_VAL, c_param);
		add_edge(1 + (i - 1) * total_nodes, 1 + i * total_nodes, INF_VAL, 0);
	}
	while (spfa()) {
		augment_flow();
	}
	printf("%d\n", total_flow_cost);
	return 0;
}
